-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/silver/silver_encounter.sql. Do not edit.
-- Silver encounter: one row per visit, with its attending physician and where the patient was placed.
CREATE OR REPLACE TABLE silver_encounter AS
WITH latest AS (
    SELECT *
    FROM bronze_resources
    WHERE resource_type = 'Encounter'
    QUALIFY ROW_NUMBER() OVER (PARTITION BY resource_id ORDER BY loaded_at DESC, bronze_id DESC) = 1
),
-- Encounter.participant of type ATND (attender) pointing at a Practitioner; the first one when there are several
attending AS (
    SELECT
        l.resource_id                                                                 AS encounter_id,
        REPLACE(p.value:individual.reference::string, 'Practitioner/', '')       AS practitioner_id
    FROM latest l , LATERAL FLATTEN(input => l.raw:participant) p
    WHERE p.value:type[0].coding[0].code::string = 'ATND'
      AND p.value:individual.reference::string LIKE 'Practitioner/%'
    QUALIFY ROW_NUMBER() OVER (PARTITION BY l.resource_id ORDER BY p.index) = 1
),
-- The last place with a Location reference (the bed when beds are given), and how often the bed changed
places AS (
    SELECT
        encounter_id,
        location_id                                                                   AS last_location_id,
        GREATEST(COUNT(CASE WHEN physical_type = 'bd' THEN 1 END) OVER (PARTITION BY encounter_id) - 1, 0) AS bed_moves
    FROM silver_encounter_location
    WHERE location_id IS NOT NULL
    QUALIFY ROW_NUMBER() OVER (PARTITION BY encounter_id ORDER BY entry_index DESC) = 1
)
SELECT
    l.resource_id                                                  AS encounter_id,
    REPLACE(l.raw:subject.reference::string, 'Patient/', '')           AS patient_id,
    l.raw:status::string                                               AS status,
    l.raw:class.code::string                                           AS class_code,
    REPLACE(l.raw:partOf.reference::string, 'Encounter/', '')          AS part_of_encounter_id,
    l.raw:identifier[0].system::string                                 AS identifier_system,
    l.raw:identifier[0].value::string                                  AS identifier_value,
    l.raw:priority.coding[0].code::string                              AS priority_code,
    COALESCE(l.raw:type[0].text::string, l.raw:type[0].coding[0].display::string) AS encounter_type,
    TRY_CAST(SUBSTR(l.raw:period.start::string, 1, 19) AS TIMESTAMP_NTZ)                                       AS start_at,
    TRY_CAST(SUBSTR(l.raw:period.end::string, 1, 19) AS TIMESTAMP_NTZ)                                         AS end_at,
    l.source_file,
    l.loaded_at,
    a.practitioner_id                                              AS attending_practitioner_id,
    pl.last_location_id,
    COALESCE(pl.bed_moves, 0)                                      AS bed_moves
FROM latest l
LEFT JOIN attending a ON a.encounter_id = l.resource_id
LEFT JOIN places pl ON pl.encounter_id = l.resource_id;
